use graham_ledger::{Ledger,OpeningInput,OpeningPosition,ValuationQuery,ValuationResponse};
fn later_history_job(l:&mut Ledger,q:&ValuationQuery)->graham_ledger::ValuationJob{l.begin_valuation_refresh(q,now()+62,false).unwrap().unwrap()}
fn now()->i64{chrono::DateTime::parse_from_rfc3339("2026-10-26T12:00:00Z").unwrap().timestamp()}
#[test]
fn historical_multi_currency_valuation_preserves_original_balances_and_cash_distribution(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let c=l.create_account("人民币","CNY").unwrap();let u=l.create_account("美元","USD").unwrap();let h=l.create_account("港币","HKD").unwrap();
 for(a,cash)in [(&c,"720"),(&u,"100"),(&h,"780")]{let positions=if a==&u{vec![OpeningPosition{market:"US".into(),code:"AAPL".into(),kind:"stock".into(),name:"苹果".into(),currency:"USD".into(),quantity:"10".into(),cost:"2000".into(),reference_price:None}]}else{vec![]};l.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),cash:cash.into(),positions,note:"".into()},None).unwrap();}
 let before=l.snapshot().unwrap();let mut query=ValuationQuery{account_ids:vec![],currency:"CNY".into(),date:Some("2026-10-23".into())};let missing=l.valuation(&query,now(),false).unwrap();assert!(!missing.complete);assert!(missing.total.is_none());assert_eq!(missing.known_total.as_deref(),Some("720.00"));let job=l.begin_valuation_refresh(&query,now(),false).unwrap().unwrap();assert_eq!(job.keys.len(),3);
 let response:ValuationResponse=serde_json::from_value(serde_json::json!({"feed":"valuation","points":[{"key":{"market":"USD","code":"CNY","kind":"fx"},"date":"2026-10-23","value":"7.2","currency":"CNY","source":"yfinance / Yahoo Finance","basis":"daily_close","sourceTime":"2026-10-23 [Europe/London]","quotedAt":null},{"key":{"market":"USD","code":"HKD","kind":"fx"},"date":"2026-10-23","value":"7.8","currency":"HKD","source":"yfinance / Yahoo Finance","basis":"daily_close","sourceTime":"2026-10-23 [Europe/London]","quotedAt":null},{"key":{"market":"US","code":"AAPL","kind":"stock"},"date":"2026-10-23","value":"250","currency":"USD","source":"yfinance / Yahoo Finance","basis":"split_checked","sourceTime":"2026-10-23 [America/New_York]","quotedAt":null}],"errors":[],"error":null})).unwrap();l.finish_valuation_refresh(&job,&response,now()+1).unwrap();let state=l.valuation(&query,now()+2,false).unwrap();assert!(state.complete);assert_eq!(state.total.as_deref(),Some("20160.00"));let usd=state.distribution.iter().find(|d|d.currency=="USD").unwrap();assert_eq!(usd.cash.as_deref(),Some("100.00"));assert_eq!(usd.securities.as_deref(),Some("2500.00"));assert_eq!(usd.known_original.as_deref(),Some("2600.00"));query.currency="USD".into();assert_eq!(l.valuation(&query,now()+2,false).unwrap().total.as_deref(),Some("2800.00"));query.currency="HKD".into();assert_eq!(l.valuation(&query,now()+2,false).unwrap().total.as_deref(),Some("21840.00"));assert_eq!(l.snapshot().unwrap().accounts,before.accounts);assert_eq!(l.snapshot().unwrap().positions,before.positions);
 query.currency="CNY".into();let next=later_history_job(&mut l,&query);let bad:ValuationResponse=serde_json::from_value(serde_json::json!({"feed":"valuation","points":[],"errors":[{"key":{"market":"US","code":"AAPL","kind":"stock"},"error":"后续拆股校验失效","invalidates":true}],"error":null})).unwrap();l.finish_valuation_refresh(&next,&bad,now()+63).unwrap();let invalid=l.valuation(&query,now()+64,false).unwrap();assert!(invalid.total.is_none(),"拆股口径失效后不能沿用旧价格宣称完整");assert_eq!(invalid.known_total.as_deref(),Some("2160.00"));
 query.date=Some("2026-10-22".into());let earlier=l.valuation(&query,now()+2,false).unwrap();assert!(!earlier.complete);assert!(earlier.total.is_none());assert!(earlier.missing.iter().any(|m|m.contains("期初")));
}

#[test]
fn reference_fx_never_replaces_actual_exchange_amounts_or_supplies_a_different_historical_day(){
 let dir=tempfile::tempdir().unwrap();let mut l=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let c=l.create_account("人民币","CNY").unwrap();let u=l.create_account("美元","USD").unwrap();l.save_opening(&OpeningInput{account_id:c.clone(),occurred_on:"2026-10-22".into(),cash:"7200".into(),positions:vec![],note:"".into()},None).unwrap();l.record_movement(&graham_ledger::MovementInput{from_account_id:c.clone(),to_account_id:u.clone(),occurred_on:"2026-10-23".into(),kind:"exchange".into(),from_currency:"CNY".into(),to_currency:"USD".into(),from_amount:"7200".into(),to_amount:"1000".into(),actual_rate:"0.13888889".into(),fee:"0".into(),fee_side:"from".into(),note:"实际成交".into()}).unwrap();let before=l.snapshot().unwrap();let query=ValuationQuery{account_ids:vec![],currency:"CNY".into(),date:None};let job=l.begin_valuation_refresh(&query,now(),false).unwrap().unwrap();
 assert!(job.keys.iter().any(|k|k.code=="HKD"),"当前后台报价应覆盖切换港币汇总所需汇率");
 let response:ValuationResponse=serde_json::from_value(serde_json::json!({"feed":"valuation","points":[{"key":{"market":"USD","code":"CNY","kind":"fx"},"date":null,"value":"8","currency":"CNY","source":"yfinance / Yahoo Finance","basis":"reference_quote","sourceTime":"2026-10-26T11:59:00Z","quotedAt":"2026-10-26T11:59:00Z"}],"errors":[],"error":null})).unwrap();l.finish_valuation_refresh(&job,&response,now()+1).unwrap();assert_eq!(l.valuation(&query,now()+2,false).unwrap().total.as_deref(),Some("8000.00"));let single=ValuationQuery{account_ids:vec![u],currency:"USD".into(),date:None};assert_eq!(l.valuation(&single,now()+2,false).unwrap().total.as_deref(),Some("1000.00"));let historical=ValuationQuery{account_ids:vec![],currency:"CNY".into(),date:Some("2026-10-23".into())};let missing=l.valuation(&historical,now()+2,false).unwrap();assert!(!missing.complete);assert!(missing.total.is_none());assert!(missing.missing.iter().any(|s|s.contains("汇率")));assert!(l.begin_valuation_refresh(&historical,now()+2,false).unwrap().is_some(),"历史查询不应被最新参考汇率的五分钟间隔阻塞");
 assert!(l.begin_valuation_refresh(&query,now()+60,false).unwrap().is_none());let retry=l.begin_valuation_refresh(&query,now()+302,false).unwrap().unwrap();let mut bad=response;bad.points[0].value="1".into();bad.points[0].quoted_at=Some("2026-10-26T11:58:00Z".into());bad.points[0].source_time=bad.points[0].quoted_at.clone();l.finish_valuation_refresh(&retry,&bad,now()+303).unwrap();let cached=l.valuation(&query,now()+304,false).unwrap();assert_eq!(cached.total.as_deref(),Some("8000.00"));assert!(cached.warnings.iter().any(|w|w.contains("沿用缓存")));assert!(l.begin_valuation_refresh(&query,now()+364,false).unwrap().is_none(),"最新汇率失败也不能突破五分钟间隔");assert_eq!(l.snapshot().unwrap().accounts,before.accounts);assert_eq!(l.snapshot().unwrap().movements[0].input,before.movements[0].input);
}
#[test]
fn receivables_become_cash_once_on_the_actual_payment_date_and_partial_values_have_no_shares(){
 let dir=tempfile::tempdir().unwrap();let path=dir.path().join("ledger.sqlite3");let mut l=Ledger::open(&path).unwrap();let a=l.create_account("分红账户","USD").unwrap();l.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-22".into(),cash:"10".into(),positions:vec![],note:"".into()},None).unwrap();l.record_dividend(&graham_ledger::DividendInput{account_id:a,occurred_on:"2026-10-23".into(),paid_on:Some("2026-10-26".into()),status:"paid".into(),market:"US".into(),code:"AAPL".into(),kind:"stock".into(),name:"苹果".into(),currency:"USD".into(),gross:"120".into(),tax:"20".into(),net:"100".into(),note:"".into()}).unwrap();let mut query=ValuationQuery{account_ids:vec![],currency:"USD".into(),date:Some("2026-10-23".into())};let historical=l.valuation(&query,now(),false).unwrap();assert_eq!(historical.total.as_deref(),Some("110.00"));let usd=historical.distribution.iter().find(|d|d.currency=="USD").unwrap();assert_eq!(usd.cash.as_deref(),Some("10.00"));assert_eq!(usd.receivables.as_deref(),Some("100.00"));query.date=None;let current=l.valuation(&query,now(),false).unwrap();assert_eq!(current.total.as_deref(),Some("110.00"));let usd=current.distribution.iter().find(|d|d.currency=="USD").unwrap();assert_eq!(usd.cash.as_deref(),Some("110.00"));assert_eq!(usd.receivables.as_deref(),Some("0.00"));query.currency="CNY".into();let missing=l.valuation(&query,now(),false).unwrap();assert!(missing.total.is_none());assert!(missing.distribution.iter().all(|d|d.share.is_none()));drop(l);let l=Ledger::open(&path).unwrap();assert!(l.valuation(&query,now(),false).unwrap().total.is_none());
}
